package com.travelbird.ai.service;
import com.travelbird.ai.dto.internal.*;import com.travelbird.ai.entity.*;import com.travelbird.ai.repository.*;import com.travelbird.place.repository.PlaceRepository;import com.travelbird.global.error.*;import java.time.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AiPreviewPersistenceService{private final AiRecommendationJobRepository jobs;private final AiTripPreviewRepository previews;private final PlaceRepository places;private final Clock clock;public AiPreviewPersistenceService(AiRecommendationJobRepository j,AiTripPreviewRepository p,PlaceRepository places,Clock c){jobs=j;previews=p;this.places=places;clock=c;}@Transactional public Long persist(Long jobId,AiCallbackRequest request){var job=jobs.findByIdForUpdate(jobId).orElseThrow(()->new BusinessException(ErrorCode.AI_JOB_NOT_FOUND));var existing=previews.findByJobId(jobId);if(existing.isPresent())return existing.get().getId();if(job.getStatus()!=BackendAiJobStatus.PROCESSING)return null;var now=LocalDateTime.now(clock);var preview=AiTripPreview.temporary(job,job.getUserId(),AiTextEscaper.escape(request.tripTitle()),AiTextEscaper.escape(request.summary()),now);for(var rd:request.days()){var day=new AiPreviewDay(rd.dayNumber());preview.addDay(day);for(var rp:rd.places()){var place=places.findById(rp.placeId()).orElseThrow(()->new BusinessException(ErrorCode.INVALID_AI_RESPONSE));day.add(new AiPreviewPlace(place,rp.order(),AiTextEscaper.escape(rp.reason())));}}previews.saveAndFlush(preview);job.succeed(now);return preview.getId();}}

